var {TypeDB, SessionType, TransactionType} = require("typedb-client")
var apiUtils = require("../util");

var fs  = require("fs")
var path = require("path")


var host= ""
var database = ""
var client = ""
var session = ""
var transaction = ""
var typeql_schema_dict = {}
// H O S T
// set server name
function set_host(req, res){
    var opts = {
        user: req.user,
        host: req.params[0],
        req: apiUtils.getRequestLogObject(req)
    }
    // console.log("Setting typedb host as : ", req.body.server)
    host = req.body.server;
    create_client(host).then(async function (client)
    {
        let database_list = await client.databases.all();
        let db_names = []
        for (const db in database_list){
            db_names.push(database_list[db]["_name"])
        }
        res.send(db_names);
    }).catch(function(err){
        apiUtils.rejectHandler(req, res, err);
    })
}
function get_host(req, res){
    res.send(host);
    return
}



// C L I E N T
async function create_client(host){
    client = await TypeDB.coreClient(host);
    return client
    // notify node-red of client exception
}
async function close_client(){
    await client.close();
    return
}
function get_client(){
    return client;
}
// D A T A B A S E
// list of all database
async function list_databases(req,res){
    try{
        let dbs = []
        let databases = await client.databases.all()
        for (const index in databases){
            dbs.push(databases[index]["_name"])
        }
       res.send(dbs); 
       return 
    }catch(exception){
        return exception
    }
}
// connect to a database 
async function set_database(db){
    try
    {
        // console.log("Setting database to : ", db)
        database = db
        return
    }catch(exception){
        console.log("Exception @set_database: ", exception)
        return exception
    }
}
//create database
async function create_database(){
    try{
    await client.databases.create(database)
    }catch(exception){
        console.log("Exception @create_database: ", exception)
        return exception
    } 
}
//delete a database
async function delete_database(){
    console.log("Deleting database: ", database)
    await(await client.databases.get(database)).delete();
}



//S E S S I O N S
async function create_session(session_type){
    try{
        // console.log("Creating session to ", database, " of type  ", session_type);
        if(session_type === "DATA"){
            session = await client.session(database,SessionType.DATA);
        }else if(session_type === "SCHEMA"){
            session = await client.session(database,SessionType.SCHEMA);
        }
        return
    }catch(exception){
        console.log("Exception @ create_session: ", exception);
        return exception
    }
}
async function close_session(){
    await session.close();
}
// T R A N S A C T I O N S
async function create_transaction(transaction_type){
    try{
        // console.log("Creating transaction to ", database, " of type  ", transaction_type);
        if(transaction_type === "READ"){
            transaction = await session.transaction(TransactionType.READ);
        }else if(transaction_type === "WRITE"){
            transaction = await session.transaction(TransactionType.WRITE);
        }
    }catch(exception){
        console.log("Exception @create_transaciton: ", exception);
        return exception;
    }
}

async function close_transaction(transaction_type){
    try{    
        if(transaction_type === "READ"){
            transaction.close();
        }else if(transaction_type === "WRITE"){
            console.log("committing transaction ... ")
            await transaction.commit();
            console.log("finished committing transaction ")
        }
        return;
    }catch(exception){
        console.log(exception);
        throw exception;
    }
}


// K N O W L E D G E
async function knowledge(req, res){
    try{
        opts = req.body;
        set_database(opts.database);
        await create_session(opts.session_type);
        await create_transaction(opts.transaction_type);

        // if new schema and writing
        if(opts.session_type=== "SCHEMA" && opts.transaction_type === "WRITE" ){
            try{
                await transaction.query.define(opts.statement);
                await close_transaction();
                session.close()
                res.send("Successfully added schema to database " + database)
            }catch(exception){
                await close_transaction();
                session.close();
                throw exception
            }
        }
        // if reading schema
    }catch(exception){
        res.status(500).send(exception.message)
    }
}


// C A U S A L

async function geminos_schema(opts , res){
    const promise = new Promise (function(resolve,reject){
        fs.readFile("./packages/node_modules/@node-red/editor-api/lib/admin/meta_model_schema.tql" ,"utf-8", async function (err,data,res){
            if(err) reject(err)
            // console.log("data ", data)
            console.log("defining causal model schema ")
            try{
                await create_session("SCHEMA");
                await create_transaction("WRITE");
                try{
                    // defines causal meta model schema
                    await transaction.query.define(data);
                }catch(exception){
                    console.log("Defining geminos model schema " ,"\n", exception);
                    throw exception;
                } 
                try{
                    await close_transaction("WRITE");
                    await session.close();
                    await create_session("DATA");
                    await create_transaction("WRITE");
                    await insert_iteratively(opts.geminos_schema_dict);
                    if(transaction.isOpen()){
                        await closes_transaction("WRITE")
                    }
                    if(session.isOpen()){
                        await session.close();
                    }
                }catch(exception){
                    console.log("Exception at writing instances to geminos model schema ", exception);
                    throw exception;
                }
                resolve("Added new causal model instance to database");
            }catch(exception){
                console.log("caught exception b ")
                reject(exception)
            }
        })
    })
    promise.then( (value) => { 
        console.log("Resolving ", value)
        res.send(value)
    }).catch( (err) =>{ 
        console.log("Caught error")
            res.send(err.message)
        })
}

async function commit_section(gem_schema_key, type){
    // create transaction
    await create_transaction("WRITE")
    this.typeql_schema_dict[gem_schema_key] = this.typeql_schema_dict[gem_schema_key].split(type); 

    if(type === "match"){
        this.typeql_schema_dict[gem_schema_key].forEach(  async function(statement){
            if(statement.length > 0){
                statement = "match" + statement;
                await transaction.query.insert(statement);
            }
        });
    }else if(type===";"){
        this.typeql_schema_dict[gem_schema_key].forEach(  async function(statement){
            if(statement.length > 2 ){
                statement += ";"
                await transaction.query.insert(statement); 
            }
        });
    }
    // commit transaction 
    await close_transaction("WRITE")
}

// INSERT STATEMENTS
async function insert_iteratively(typeql_schema_dict){
    try{
        this.typeql_schema_dict = typeql_schema_dict

        // entities
        await commit_section("entity", ";")

        // relation
        await commit_section("relation", ";")

        // events
        await commit_section("events",";")

        //events
        await commit_section("submodel_events", "match")
        
        //paths 
        await commit_section("paths","match")

        // submodel paths: "a causal model contains this causal path"  [ causal_model ---> causal_path ]
        await commit_section("submodel_paths", "match")

        // submodel submodels
        await commit_section("submodel_submodels", "match")
 

        // [ KNOWLEDGE MODEL SCHEMA ]
        // [actors]
        await commit_section("actors", "match")

        // Connect all relations to knowledge model 
        await commit_section("kg_relation", "match")

        // CONNECT ENTITIES TO KNOWLEDGE MODELS
        await commit_section("kg_entity", "match")
        
        // Connect all parent-child entities
        await commit_section("entity_sub", "match")

        // Connect all parent-child relations
        await commit_section("relation_sub","match")

        await commit_section("roles","match")

        await commit_section("roles_subject", "match")

        await commit_section("roles_predicate", "match")

        await commit_section("roles_typeof", "match")

        //connect attribute instance to attribute type
        await commit_section("km_attribute", ";")

        // connect attribute instance to entity through properties relation [modified , modifier]
        await commit_section("properties", "match")

        await commit_section("attribute_types", "match")
        console.log("Finished iterative insert")
    }catch(exception){
        console.log(exception)
        return exception
    }
}

async function causal(req, res){
    try{
        opts = req.body;
        if( await client.databases.contains(opts.database) ){
            set_database(opts.database);
            await delete_database();
            await create_database(opts.database);
            await geminos_schema(opts,res)
        }
    }catch(exception){
        res.status(500).send(exception.message)
    }
}

// [ DEPLOY ]
async function deploy(req,res){
    // console.log("In depploy")
    try{
        await deploy_graph_schema(req,res);
        await deploy_geminos_schema(req,res);
    }catch(exception){
        console.log("Caught exception @deploy" , exception)
        res.status(500).send(exception.message)
    }
}  

async function deploy_graph_schema(req, res){
    // console.log("Deploy graph schema")
    //clear previous schema in graph
    try{
        let opts = req.body
        // console.log("Opts: ", opts.database)
        // console.log(opts.data_schema)
        let db_exists = await client.databases.contains(opts.database)
        if(db_exists){
            await set_database(opts.database)
            await delete_database()
            await create_database()
            await create_session("SCHEMA")
            await create_transaction("WRITE")
            await transaction.query.define(opts.data_schema);
            await close_transaction("WRITE")
            await session.close();
        }else{
            await set_database(opts.database)  
            await create_database()
            await create_session("SCHEMA")
            await create_transaction("WRITE")
            await transaction.query.define(opts.data_schema);  
            await close_transaction("WRITE")
            await session.close();
        }
    }catch(exception){
        console.log("Deploy graph exception : ", exception)
        console.log(exception.message)
        console.log(exception)
        throw exception
        // res.status(500).send(exception.message)
    }
}

async function deploy_geminos_schema(req,res){
    // clear previous schema in geminos database
    try{
        opts = req.body
        let geminos_db = "geminos_models_default"
        let db_exists = await client.databases.contains(geminos_db)
        if(db_exists){
            await set_database(geminos_db);
            await delete_database()
            await create_database()
            await geminos_schema(opts, res)
        }else{
            set_database(geminos_db)
            await create_database()
            await geminos_schema(opts,res)
        }
    }catch(exception){
        res.status(500).send(exception.message)
    }
}

